SELECT ?winnerFilm ?winnerFilmLabel ?winnerDirector ?winnerDirectorLabel ?birth1 ?birth2 WHERE {
  BIND(<http://dbpedia.org/resource/Who's_Your_Brother%3F> AS ?f1)
  BIND(<http://dbpedia.org/resource/The_Last_Outpost_(1951_film)> AS ?f2)
  { ?f1 dbo:director ?d1 } UNION { ?f1 dbp:director ?d1 }
  { ?f2 dbo:director ?d2 } UNION { ?f2 dbp:director ?d2 }
  OPTIONAL { ?d1 dbo:birthDate ?bd1 }
  OPTIONAL { ?d1 dbp:birth_date ?bd1alt }
  OPTIONAL { ?d2 dbo:birthDate ?bd2 }
  OPTIONAL { ?d2 dbp:birth_date ?bd2alt }
  BIND(COALESCE(?bd1, ?bd1alt) AS ?birth1)
  BIND(COALESCE(?bd2, ?bd2alt) AS ?birth2)
  FILTER(bound(?birth1) && bound(?birth2))
  BIND(IF(?birth1 < ?birth2, ?f1, ?f2) AS ?winnerFilm)
  BIND(IF(?birth1 < ?birth2, ?d1, ?d2) AS ?winnerDirector)
  OPTIONAL { ?winnerFilm rdfs:label ?winnerFilmLabel . FILTER(lang(?winnerFilmLabel) = "en") }
  OPTIONAL { ?winnerDirector rdfs:label ?winnerDirectorLabel . FILTER(lang(?winnerDirectorLabel) = "en") }
}

